SELECT so.id, so.order_no, so.platform_order_no, so.platform_id, p.name AS platform_name, p.color AS platform_color, so.warehouse_id, w.name AS warehouse_name, so.receiver_name, so.receiver_phone, so.receiver_address, so.receiver_name_hash, so.receiver_phone_hash, so.order_status, so.total_amount, so.remark, so.paid_at, so.shipped_at, so.finished_at, so.deleted, so.created_at, so.updated_at FROM sales_order so LEFT JOIN warehouse w ON so.warehouse_id = w.id LEFT JOIN platform p ON so.platform_id = p.id AND p.deleted = 0 WHERE so.deleted = 0
AND so.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND so.platform_order_no LIKE CONCAT('%', #{platformOrderNo}, '%')
AND so.receiver_name_hash = #{receiverNameHash}
AND so.receiver_phone_hash = #{receiverPhoneHash}
AND so.order_status = #{orderStatus}
AND so.warehouse_id = #{warehouseId}
ORDER BY id DESC

SELECT so.id, so.order_no, so.platform_order_no, so.warehouse_id, w.name AS warehouse_name, so.receiver_name, so.receiver_phone, so.receiver_address, so.receiver_name_hash, so.receiver_phone_hash, so.order_status, so.total_amount, so.remark, so.paid_at, so.shipped_at, so.finished_at, so.deleted, so.created_at, so.updated_at FROM sales_order so LEFT JOIN warehouse w ON so.warehouse_id = w.id WHERE so.deleted = 0
AND ( so.order_no LIKE CONCAT('%', #{keyword}, '%') OR so.platform_order_no LIKE CONCAT('%', #{keyword}, '%')
OR so.receiver_name_hash = #{receiverNameHash}
OR so.receiver_phone_hash = #{receiverPhoneHash}
)
AND so.order_status = #{orderStatus}
AND so.warehouse_id = #{warehouseId}
ORDER BY so.id DESC

